import { chromium } from '/Users/vojta/Dev/evangelist-exchange/node_modules/playwright/index.mjs';
import { createWorldFromMenu, openGameAction } from '/Users/vojta/Dev/protocodus.github.io/fun/transport/tests/browser-start.mjs';
