await page.screenshot({ path:`${OUT}/03-start.png` });
await page.locator('[data-view="build"]').first().click();
await page.waitForTimeout(400);
await page.screenshot({ path:`${OUT}/04-build.png` });
await page.locator('[data-view="routes"]').first().click();
await page.waitForTimeout(400);
await page.screenshot({ path:`${OUT}/05-routes.png` });
await page.locator('[data-view="industry"]').first().click();
await page.waitForTimeout(400);
await page.screenshot({ path:`${OUT}/06-industry.png` });
await page.locator('[data-view="towns"]').first().click();
await page.waitForTimeout(400);
await page.screenshot({ path:`${OUT}/07-towns.png` });
await page.locator('[data-view="towns"]').first().click();
await page.waitForTimeout(300);
// click center of map to inspect
await page.mouse.click(720, 480);
await page.waitForTimeout(400);
await page.screenshot({ path:`${OUT}/08-inspect.png` });
await page.keyboard.press('Escape');
await page.locator('[data-speed="8"]').click();
await page.waitForTimeout(8000);
await page.screenshot({ path:`${OUT}/09-after8s.png` });
console.log(JSON.stringify(await page.evaluate(() => ({ keys:Object.keys(window.transport||{}), money:window.transport.game.money, day:window.transport.game.day, routes:window.transport.game.routes.length, notes:(window.transport.game.notifications||[]).slice(-5) })), null, 1));
console.log('errors', errors);
await browser.close();
EOF
cd $SP && node tour.mjs $SP/shots

