        required: ['id', 'title', 'problem', 'proposal', 'files', 'impact', 'effort', 'risk', 'verification'],
      },
    },
  },
  required: ['dimension', 'summary', 'proposals'],
}

const VERDICTS = {
  type: 'object',
  properties: {
