export const meta = {
  name: 'transport-implement',
  description: 'Implement verified Transport improvements batch by batch in isolated worktrees, merge into transport-playability, then review and fix',
  phases: [
    { title: 'Implement', detail: 'one agent per item, each in its own git worktree' },
    { title: 'Merge', detail: 'squash-merge the batch, run suites and a smoke play' },
    { title: 'Final review', detail: 'code review and play-tests of the integrated branch' },
    { title: 'Fix', detail: 'verify and fix confirmed review findings' },
  ],
}

const SP = 'REDACTED'
const REPO = '/Users/vojta/Dev/protocodus.github.io'
const BRANCH = 'transport-playability'
const PW = '/Users/vojta/Dev/evangelist-exchange/node_modules/playwright/index.mjs'
const BASE0 = args.base

const GAME = `The browser game "Transport" lives in fun/transport of the repo ${REPO} — an isometric transport & city-building game (static ES modules, no build step, Canvas 2D, ~770 KB JS: app.js UI/input, model.js simulation, renderer.js, plus many modules; README.md is the player guide, ARCHITECTURE.md the module reference, PERFORMANCE.md perf notes). A multi-agent review played the game and verified a plan of improvements; the per-item specs live in ${SP}/specs/<id>.md and shared safety rules in ${SP}/specs/_rules.md.
Browser tooling: Playwright at ${PW}; launch chromium with {channel:'chrome', headless:true, args:['--use-angle=metal','--enable-gpu','--ignore-gpu-blocklist']}. Chrome CANNOT launch inside the Bash sandbox, so every node command that starts a browser, every background server start, and kill/pkill/lsof must run with dangerouslyDisableSandbox: true. Browser checks read TRANSPORT_URL and TRANSPORT_PLAYWRIGHT env vars (and often TRANSPORT_OUTPUT). fun/transport/tests/browser-start.mjs has createWorldFromMenu/waitForGameReady/openGameAction helpers; window.transport exposes {game, renderer, speed, setSpeed, setTool, setView, inspect, persist}. No-cache static server script: python3 ${SP}/serve.py <port> <root-dir>.
Reviewer experiment scripts (useful benchmarks/repros) are in ${SP}/review/<dimension>/ and ${SP}/verify/<dimension>/; they target port 8841 — copy and repoint them.
Code style: match the surrounding code exactly — dense one-line functions, same naming, idioms and (sparse) comment density; never reformat or reflow existing lines; no new dependencies. model.js stays DOM-free. Saves must stay compatible and the simulation deterministic. UI copy is sentence case (no ALL-CAPS labels), warm off-white panels, dark green, orange accent.`

const IMPL = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    status: { type: 'string', enum: ['done', 'partial', 'failed'] },
    branch: { type: 'string' },
    sha: { type: 'string', description: 'final commit sha on the branch (empty if nothing committed)' },
    summary: { type: 'string', description: 'what was implemented, player-visible effect' },
    deviations: { type: 'string', description: 'where and why the implementation differs from the spec' },
    nodeTests: { type: 'string', description: 'full suite result line (pass/fail counts) and new tests added' },
    browserChecks: { type: 'string', description: 'which browser checks ran and their results' },
    visualCheck: { type: 'string', description: 'screenshots taken (paths) and what they showed' },
    notesForMerger: { type: 'string', description: 'anything the integrator must know: shared helpers added, lines touched in hot files, expected conflicts' },
  },
  required: ['id', 'status', 'branch', 'sha', 'summary', 'deviations', 'nodeTests', 'browserChecks', 'visualCheck', 'notesForMerger'],
}

const MERGE = {
  type: 'object',
  properties: {
    sha: { type: 'string', description: 'HEAD of transport-playability after the batch' },
    merged: { type: 'array', items: { type: 'string' } },
    skipped: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, reason: { type: 'string' } }, required: ['id', 'reason'] } },
    conflictNotes: { type: 'string' },
    nodeTests: { type: 'string' },
    browserChecks: { type: 'string' },
    smoke: { type: 'string', description: 'what the smoke play showed, screenshots' },
    integrationFixes: { type: 'string' },
    openIssues: { type: 'string' },
  },
  required: ['sha', 'merged', 'skipped', 'conflictNotes', 'nodeTests', 'browserChecks', 'smoke', 'integrationFixes', 'openIssues'],
}

function implPrompt(it, batch, base, port) {
  const others = batch.items.filter(o => o.id !== it.id).map(o => `- ${o.id} — ${o.title} (files: ${o.files.join(', ')})`).join('\n') || '- none'
  return `${GAME}

YOUR TASK: implement exactly ONE planned improvement: "${it.id}" — ${it.title}.
Read your full spec first: ${SP}/specs/${it.id}.md (the "Spec" section is authoritative; source proposals are background). Read ${SP}/specs/_rules.md. Then read the code the spec names before editing.

WORKTREE: you run in your own private git worktree (your current working directory; find its root with git rev-parse --show-toplevel). Setup:
1. git rev-parse HEAD must equal ${base}. If it does not, run git reset --hard ${base} (this is your private worktree, that is safe).
2. git checkout -B tp/${it.id}
All edits happen inside THIS worktree. Never modify ${REPO} (the main checkout, also serving other agents) or any other worktree.

PARALLEL WORK: these items of the same batch are being implemented at the same time in other worktrees and will be squash-merged together with yours afterwards:
${others}
Stay strictly inside your spec's scope. In shared hot files (app.js, renderer.js, model.js, CSS) touch only the functions/lines your spec names, keep edits minimal and local, never reflow existing lines, and put new CSS on new lines where your spec says, so the merge stays clean.

SERVER AND BROWSER: start python3 ${SP}/serve.py ${port} <your-worktree-root> in the background (run_in_background: true, dangerouslyDisableSandbox: true). Your game URL is http://127.0.0.1:${port}/fun/transport/. Run browser checks as TRANSPORT_URL=http://127.0.0.1:${port}/fun/transport/ TRANSPORT_PLAYWRIGHT=${PW} TRANSPORT_OUTPUT=${SP}/impl/${it.id}/<check-name> node fun/transport/tests/<check>.mjs from your worktree root, with dangerouslyDisableSandbox: true. Kill your server when done.

VERIFY:
- Add the node tests your spec lists (prefer writing them first and seeing them fail), then implement until they pass.
- Before committing run the full node suite from your worktree root: node --test --test-concurrency=3 fun/transport/tests/*.test.mjs — it must be fully green (baseline 417 tests plus yours). Only tests the spec names as deliberate policy changes may change expectations.
- Run the browser checks your spec names, adding the new assertions it lists to them.
- For anything visible, take screenshots of the real game in your worktree and LOOK at them with the Read tool. Judge honestly whether it looks good, reads clearly and fits the existing design; iterate if not.
- Update the README.md / ARCHITECTURE.md sections your spec names, in the documents' existing voice.

COMMIT on tp/${it.id}: review git status first (never commit screenshots, scratch files or .playwright-mcp), then git add the changed files under fun/transport and commit with a message "<type>(transport): <concise summary>" (type feat, fix or perf), a short body, and the final line
Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Do not push. Do not merge into any other branch.

If part of the spec proves wrong or infeasible once you are in the code, adapt sensibly and report the deviation precisely. If you get blocked, commit what is solid and report status "partial". Return the structured result.`
}

function mergePrompt(batch, bIndex, impls, base) {
  return `${GAME}

YOU ARE THE INTEGRATOR for ${batch.name} (batch ${bIndex + 1}). Work in the main checkout ${REPO} on branch ${BRANCH} (cd there; use absolute paths). Implementers worked in parallel private worktrees from base ${base} and committed to branches tp/<id>. Their reports:
${JSON.stringify(impls, null, 1)}

STEPS
1. git -C ${REPO} status must be clean on ${BRANCH} with HEAD ${base}. If not, investigate; do not discard anything you did not create — report it instead.
2. Integrate each item that has a commit, in this order: ${batch.items.map(i => i.id).join(', ')}. For each: git merge --squash <sha or tp/<id>>; resolve conflicts preserving BOTH sides' intent (read both items' specs in ${SP}/specs/<id>.md; long lines in app.js/style.css/renderer.js need careful hand-merging — never drop either side's functionality); then commit with that implementer's own commit message (git log -1 --format=%B <sha>). One commit per item. If an item is unusable (failed, or breaks things you cannot reconcile), skip it and say why.
3. After all items: node --check every changed JS file; run the full node suite: node --test --test-concurrency=4 fun/transport/tests/*.test.mjs (must be green); run the union of browser checks the batch's specs named, against the main checkout served at http://127.0.0.1:8841/fun/transport/ (a no-store server should already be running there; if curl gets no 200, start python3 ${SP}/serve.py 8841 ${REPO} in the background with dangerouslyDisableSandbox). Env: TRANSPORT_URL=http://127.0.0.1:8841/fun/transport/ TRANSPORT_PLAYWRIGHT=${PW} TRANSPORT_OUTPUT=${SP}/merge/b${bIndex + 1}/<check>.
4. Smoke play with a Playwright script in ${SP}/merge/b${bIndex + 1}/: fresh taiga world (seed 1847) at 1440x900, open Build/Routes/Industries/Towns, build a short road and a stop, create a route through the form, run 8x for 20 s, then a 390x844 touch viewport. Collect console errors and page errors, take screenshots and LOOK at them. Anything broken by the combination of items is your job to fix.
5. Fix integration problems (semantic conflicts, duplicated helpers, broken tests, visual collisions between items) with minimal, style-matching edits; commit as "fix(transport): integrate batch ${bIndex + 1}" with a body and the final line Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>.
RULES: never push; never touch the main branch; never delete tp/* branches; only use git reset --hard HEAD / git merge --abort to back out an in-progress item merge. Return sha = git rev-parse HEAD at the end.`
}

const FINDINGS = {
  type: 'object',
