  { key: 'mobile-and-perf', prompt: `(1) Play the integrated game on a 390x844 and a 320x640 touch viewport (hasTouch, isMobile): management drawer, building by touch, route form, inspector, toasts, goal card, pinch/pan via CDP Input.dispatchTouchEvent; report layout collisions, clipped text and gesture problems. (2) Performance regression check against the base: git -C ${REPO} archive ${BASE0} fun/transport assets | tar -x -C ${SP}/final/base, serve it on port 8845 and compare with the integrated build on 8841: paused-app redraws over 3 s (must stay 0), warm frame time at Town and Region zoom at 1x/8x on seed 1847, autosave stall, script time per second at 8x. Report regressions with numbers.` },
]
const reviews = await parallel(REVIEWERS.map(r => () => agent(`${GAME}\n\nFINAL REVIEW of branch ${BRANCH} at ${base} in ${REPO}, served (no-store) at http://127.0.0.1:8841/fun/transport/. REVIEW ONLY: do not modify files in the repo; scratch dir ${SP}/final/${r.key}/.\n\n${r.prompt}`, { label: `review:${r.key}`, phase: 'Final review', schema: FINDINGS })))
const findings = reviews.filter(Boolean).flatMap((r, i) => r.findings.map(f => ({ reviewer: REVIEWERS[i].key, ...f })))
