export const meta = {
  name: 'transport-ttd-design',
  description: 'Design Transport Tycoon-inspired mechanics and long-horizon achievements that fit the game, keep play simple and never forced',
  phases: [
    { title: 'Design', detail: 'one designer per mechanic writes an implementable spec; a simplicity audit of the whole plan' },
    { title: 'Critique', detail: 'skeptic checks fit, simplicity, balance, save compat, interactions; finalizes spec' },
    { title: 'Batch', detail: 'order and batch the accepted mechanics' },
  ],
}

const SP = 'REDACTED'
const REPO = '/Users/vojta/Dev/protocodus.github.io'
const PRINCIPLES = `DESIGN PRINCIPLES FROM THE USER (hard requirements, override anything else):
1. "Ensure the basic gameplay is simple and the player is not forced to do anything." The core loop — lay a road/rail, place stops, launch a route, watch it earn, grow — must stay as simple as it is now or simpler. Every new system must be optional to engage with and safe to ignore: no mechanic may punish the player for NOT doing something (no mandatory upkeep chores, no deadlines that hurt, no forced choices, no nagging). Goals, contracts, achievements and ratings are invitations, never obligations. New complexity lives behind optional, collapsed or on-demand UI (dialogs, inspector sections, hover), not on the default screen. Defaults must make sense without touching any setting.
2. "Anything to make it more similar to Transport Tycoon is welcome, but only fitting into our game design." Capture TTD/OpenTTD's feel and decisions adapted to this game's two-stop routes, compact economy and calm, elegant tone. No pastiche (no fake 1994 UI), no real brand names, no new raster art (code-drawn SVG/canvas pictograms are fine; vehicle art is fixed per mode).
3. "A system of challenging achievements would be nice — based on round numbers and game progress, e.g. after 100 years of playing." Long-horizon recognition that rewards mastery over decades of game time.`

const CONTEXT = `The browser game "Transport" (${REPO}/fun/transport) is an isometric transport & city-building game: static ES modules, Canvas 2D, no build step. Read fun/transport/README.md (player guide) and ARCHITECTURE.md first. Core: two-stop routes (road/rail/water), vehicles load directly from producer industry inventories / town passenger pools and are paid on delivery (model.js loadVehicle/unloadVehicle: revenue = priceFor(game, delivered*CARGO.price*(1+0.55*sqrt(pathLength-1)), arrivalDay)); yearly vehicle generations (+20% capacity, +10% speed) from January 1950, seeded inflation, towns grow from service, industries with recipes, deterministic simulation via randomAt(game, day, key, salt) (never Math.random; notify() consumes nextId which keys vehicle randomness — don't add notify() calls on simulation paths without care), saves must stay backward compatible (new fields optional + validated in validateGame + defaulted on load), model.js is DOM-free. Design language: gentle, elegant builder — warm off-white panels, dark green, orange accent, sentence case, no clutter.

${PRINCIPLES}

A large improvement plan is being implemented right now on branch transport-playability (git -C ${REPO} log --oneline 7be60d3..HEAD shows what already landed). The remaining planned items (specs in ${SP}/specs/<id>.md — read the ones relevant to you) are: slope-aware-routing, route-emphasis, service-share-growth, fleet-per-route (add/sell vehicles per route), revive-browser-checks, milestone-ladder (company goal chapters), town-needs (food/goods unlock housing tiers), route-forecast (income forecast in route form), construction-undo, cargo-lens, clickable-vehicles-and-stops, inspector-service-links, names-and-rename, route-attention, cargo-contracts (TTD-like subsidies), keyboard-map-cursor, selection-context-lines, cached-intl-formatters, hover-pick-readback, company-report-credit (company dialog with charts, year review, route leaderboard, credit line/loan), edit-route, industry-status-markers, town-street-growth, construction-ergonomics, area-zoning, active-tool-bar, mobile-layout-pass, town-outlook, plan-connection, overlay-placer-and-badges, trackpad-pan, inspector-bottom-sheet, incremental-minimap, incremental-route-replanning, lazy-atlas-densities, entity-lists, phased-modulepreload, daily-step-allocation-free. New mechanics are implemented AFTER all of those land, so build on them (company dialog, notification pipeline/News, next-goal card, route card, town inspector, forecast) instead of duplicating them.
Scratch dir for experiments: ${SP}/ttd/<id>/ (node sims welcome). Do NOT edit repository files.`

const MECHANICS = [
  { id: 'ttd-achievements', brief: `Long-horizon achievements (the user's explicit wish). A catalogue of roughly 40–60 challenging achievements built on round numbers and decades of progress, tiered where natural (e.g. bronze/silver/gold/platinum on 10× steps): lifetime units delivered (1k … 10M), lifetime revenue / company value ($1M … $1B, inflation-aware: define whether nominal or 1950 dollars and say why), vehicles in service (10 … 1,000), towns connected (10, 50, 100, every town), a single town's population (5k, 25k, 100k), one route earning a round sum in a calendar year, every cargo of the biome delivered, every production chain completed end to end, network size (1,000 / 10,000 tiles of road or rail), bridges/tunnels built, ships on water, years in business (10, 25, 50, 100 — i.e. reaching 1960/1975/2000/2050), a debt-free century, reaching the top title (if ttd-company-rating lands), plus a few playful hidden ones (never announced before unlock). Rules: pure recognition — no gameplay bonuses that would make them feel mandatory, never block anything, never nag; evaluation is cheap (incremental counters or derived at day/month boundaries; must be fine on 2048² with 10k vehicles), deterministic, and saved per company as an optional field (unlocked id → game day), with legacy saves evaluating what they already qualify for silently (no notification flood on load). Optional browser-wide "best across companies" record in localStorage (try/catch) is allowed if it fits. UI: Game menu → Achievements dialog (grouped, progress bars toward the next tier, unlock dates, hidden ones as '?'), a tasteful unlock notice through the notification pipeline (bigger/headline for gold/platinum), and a count in the company dialog. Distinguish clearly from milestone-ladder (short guided onboarding chapters) — no duplicated goals.` },
  { id: 'ttd-transit-payment', brief: `Delivery speed matters (TTD cargo payment rates). Each cargo gets TTD-style transit-time sensitivity: perishables (passengers, mail if added, food, goods, fish) lose value faster than bulk (coal, stone, ore, sand, timber). Vehicles record when their cargo was loaded (optional saved field; legacy vehicles pay as today). Payment = today's distance formula × a gentle time factor that never drops below a floor (e.g. 0.5) so nothing punishes a casual player. Show it only on demand: a "Cargo payment rates" chart (payment for 10 units over 20 tiles vs days in transit, one line per cargo) in the Chains dialog resources view or company dialog; route cards may show pay % in a tooltip/detail; the route forecast accounts for it. Calibrate with node sims across road/rail/water and route lengths so ordinary routes keep ≥90% pay (simple play unaffected), rail/upgrades become meaningfully better only for long perishable hauls, the starter economy stays net positive, and list which existing economy tests change.` },
  { id: 'ttd-full-load', brief: `TTD's "Full load" order as an optional per-route toggle (default off, so nothing changes for simple play): vehicles wait at the loading stop re-trying to load (deterministically, with the existing dwell/event-queue machinery) until full or until an optional max wait. Must interact correctly with multiple vehicles per route (fleet-per-route), spacing, transit-time payment (TTD counts transit from loading), autosave capture, save/restore of waiting state, route editing. UI: a small toggle on the route card (and in the route form's optional details); card shows "Waiting for full load · 64/80".` },
  { id: 'ttd-company-rating', brief: `TTD's company performance rating and titles, as recognition only. A 0–1000 performance score from categories adapted from TTD (vehicles making a profit, stops in use, minimum route profit, minimum and maximum income, cargo delivered, cargo types handled, money, loan) derived from existing state/history at quarter or year boundaries (cacheable; persisted only if needed, optional). Company value (money − loan + vehicle value + infrastructure estimate). A title ladder (Engineer → Traffic Manager → Transport Coordinator → Route Supervisor → Director → Chief Executive → Chairman → President → Tycoon) shown in the finances tooltip and company dialog, with a promotion notice. At the start of 2050 (100 years) an end-of-century evaluation card with the final title and score; play continues. Integrate with company-report-credit's dialog, milestone-ladder and ttd-achievements rather than duplicating them. No penalties, no demotion nagging.` },
  { id: 'ttd-vehicle-models', brief: `Named vehicle models and vehicle age, TTD style, kept light. Each mode (road bus, road truck, rail passenger, rail freight, ferry, cargo ship) gets a series of fictional model names across the yearly generations (made-up manufacturers/series, never real brands), shown wherever "Gen N" appears (route cards, purchase preview, upgrade tooltips, vehicle card). The January notice becomes "New vehicle: <name> — +20% capacity…" with the existing upgrade action. Vehicle age (optional saved purchase/upgrade day; legacy default deterministic) with a lifespan per mode; past lifespan running costs rise gently and the card shows "Old" — a soft nudge, never a breakdown or a forced replacement; upgrading renews. Per-route "Profit this year / last year" on route cards (derive from existing accounting where possible).` },
  { id: 'ttd-headlines', brief: `TTD newspaper moments, adapted: a distinct, elegant "headline" card for rare big events — first company vehicle arriving in a town ("Citizens celebrate — first bus arrives in Cedarbridge"), first train/ship ever, a town reaching a size tier, a new vehicle model, promotions (ttd-company-rating), gold/platinum achievements (ttd-achievements), industry openings (if ttd-industry-dynamics lands). Queued through the existing notification pipeline, stored in News with headline styling, never more than one on screen, rate-limited, reduced-motion safe, dismissible, never pausing or blocking play. Define precisely which events qualify and how "first arrival per town" is tracked (optional saved set or derived).` },
  { id: 'ttd-industry-dynamics', brief: `TTD's living world, gentle version: occasionally a new industry opens somewhere suitable ("New coal mine under construction near Pinehaven") — this adds opportunities. Closures are the TTD pressure mechanic and conflict with "never forced": decide carefully — e.g. only industries that were never served and sit idle for decades may quietly fade, never one the player serves or planned (an active route, a contract, a goal target), with long notice, or drop closures entirely. Deterministic (randomAt with new salts, monthly), bounded by map size, reusing existing site validation/placement code (industry-sites.js, footprints, terrain flatness). Removed industries must be handled by routes, contracts, goals, markers and saves.` },
  { id: 'ttd-town-authority', brief: `TTD's local authority, gentle version. Each town has an opinion of the company (Appalling … Outstanding) derived from service quality and disturbance (bulldozing homes/trees within the town radius). Show it in the town inspector with reasons. Optional town actions for money: advertising campaign (more passengers/mail at stops in that town for some months), fund new buildings (faster growth for a year). Costs scale with inflation and town size; effects stored as optional city fields with end days; deterministic. A low opinion must never block building or punish; at most it slightly slows growth, and ignoring the whole system must be fine. Integrate with town-outlook, town-needs and the town inspector.` },
  { id: 'ttd-mail', brief: `TTD mail. Towns generate mail proportional to population; mail travels between two different towns like passengers (reuse the passenger endpoint logic), pays more per unit, is perishable (transit payment), uses trucks/trains/ships with a code-drawn mail pictogram (cargo-icons.js style). Add it to the cargo catalogue, route form, chains/resources key, forecasts and town inspector ("Mail waiting"). Save compatible (towns in old saves start with zero mail), deterministic. Check every place that special-cases 'passengers'. Keep the route form simple: mail is just another cargo choice, inferred like the others.` },
]

const SPEC = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    title: { type: 'string' },
    fit: { type: 'string', description: 'why this belongs in this game, how it stays optional and keeps basic play simple' },
    spec: { type: 'string', description: 'complete, precise implementation spec: data model (fields, defaults, validation), simulation rules with numbers, exact functions/files to change, UI (where, copy, states), save compatibility, determinism, interactions with the planned items' },
    tests: { type: 'string', description: 'node tests to add and browser checks to run/extend' },
    files: { type: 'array', items: { type: 'string' } },
    dependsOn: { type: 'array', items: { type: 'string' }, description: 'planned item ids or other ttd ids that must land first' },
    impact: { type: 'integer', minimum: 1, maximum: 5 },
    effort: { type: 'string', enum: ['S', 'M', 'L'] },
  },
  required: ['id', 'title', 'fit', 'spec', 'tests', 'files', 'dependsOn', 'impact', 'effort'],
}
const CRITIQUE = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    verdict: { type: 'string', enum: ['accept', 'accept-revised', 'reject'] },
    reason: { type: 'string' },
    finalSpec: { type: 'string', description: 'for accept/accept-revised: the final, corrected implementation spec (complete, standalone)' },
    tests: { type: 'string' },
    files: { type: 'array', items: { type: 'string' } },
    dependsOn: { type: 'array', items: { type: 'string' } },
    impact: { type: 'integer', minimum: 1, maximum: 5 },
    effort: { type: 'string', enum: ['S', 'M', 'L'] },
  },
  required: ['id', 'verdict', 'reason', 'finalSpec', 'tests', 'files', 'dependsOn', 'impact', 'effort'],
}
const AUDIT = {
  type: 'object',
  properties: {
    summary: { type: 'string' },
    guardrails: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          target: { type: 'string', description: 'planned item id, landed commit/feature, or "general"' },
          problem: { type: 'string', description: 'how it forces the player or complicates the basic loop, with evidence' },
          change: { type: 'string', description: 'the concrete change to make (copy, default, placement, rule), precise enough to implement' },
          files: { type: 'array', items: { type: 'string' } },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
        },
        required: ['target', 'problem', 'change', 'files', 'severity'],
      },
    },
  },
  required: ['summary', 'guardrails'],
}

phase('Design')
const auditP = agent(`${CONTEXT}\n\nYOU ARE THE SIMPLICITY AND FREEDOM AUDITOR. Review (a) what already landed on branch transport-playability (git -C ${REPO} diff 7be60d3..HEAD -- fun/transport, and the live game served at http://127.0.0.1:8841/fun/transport/ — you may drive it with a Playwright script: Playwright at /Users/vojta/Dev/evangelist-exchange/node_modules/playwright/index.mjs, chromium channel 'chrome', run node with dangerouslyDisableSandbox: true; the game opens at a start menu, use fun/transport/tests/browser-start.mjs createWorldFromMenu) and (b) every remaining planned item spec in ${SP}/specs/ (the ids listed above). Find anything that forces the player (deadlines that hurt, penalties for inaction, mandatory chores, nags, blocking modals, goals presented as obligations, growth gates that make the old simple loop stop working) or that makes the basic loop harder to understand (more steps, more on-screen chrome by default, jargon). Also check the first 5 minutes of a new game stay simple. Return concrete guardrail changes (copy, defaults, placement, rules) precise enough to implement; prefer small changes that keep each feature's value. Scratch: ${SP}/ttd/audit/.`, { label: 'audit:simplicity', phase: 'Design', schema: AUDIT })

const results = await pipeline(
  MECHANICS,
  m => agent(`${CONTEXT}\n\nYOU DESIGN ONE MECHANIC: ${m.id}.\n${m.brief}\n\nRead the relevant code (model.js, settlements.js, industry-simulation.js, economy-pricing.js, data.js, gameplay-insights.js, app.js panels, save codecs/validateGame) and the relevant planned-item specs before designing. Where numbers matter, run node sims (import from ${REPO}/fun/transport/model.js etc.) to calibrate. Produce a spec an engineer can implement without guessing. Keep scope tight: the smallest version that delivers the Transport Tycoon feel while staying optional and simple.`, { label: `design:${m.id}`, phase: 'Design', schema: SPEC }),
  (d, m) => d && agent(`${CONTEXT}\n\nYou are a skeptical lead game designer and engineer reviewing a proposed mechanic for this game. Check: (1) the user's principles — is it optional, safe to ignore, free of penalties for inaction, and does it keep the basic loop and default screen simple? does it fit the calm, elegant design and two-stop route model? (2) is it correct against the actual code (open the functions it names), save-compatible, deterministic, performance-safe on 2048² maps with 10k vehicles; (3) does it duplicate or conflict with planned items (read their specs in ${SP}/specs/) or other proposed mechanics (ttd-achievements, ttd-transit-payment, ttd-full-load, ttd-company-rating, ttd-vehicle-models, ttd-headlines, ttd-industry-dynamics, ttd-town-authority, ttd-mail); (4) are the numbers sane (re-run a quick sim if balance is claimed). Verdict accept, accept-revised (write the corrected complete spec), or reject (say why). Keep what gives the TTD feel or the long-term challenge; cut what does not pay for itself or adds pressure.\n\nPROPOSED SPEC:\n${JSON.stringify(d, null, 1)}`, { label: `critique:${m.id}`, phase: 'Critique', schema: CRITIQUE }).then(c => ({ design: d, critique: c })),
)
const audit = await auditP

const accepted = results.filter(r => r && r.critique && r.critique.verdict !== 'reject')
const rejected = results.filter(r => r && r.critique && r.critique.verdict === 'reject').map(r => ({ id: r.design.id, reason: r.critique.reason }))
log(`${accepted.length} mechanics accepted, ${rejected.length} rejected; ${audit?.guardrails?.length || 0} simplicity guardrails`)

phase('Batch')
const BATCH = {
  type: 'object',
  properties: {
    batches: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, itemIds: { type: 'array', items: { type: 'string' } } }, required: ['name', 'itemIds'] } },
    notes: { type: 'string' },
  },
  required: ['batches', 'notes'],
}
const specsText = accepted.map(r => `### ${r.critique.id} (${r.design.title})\nfiles: ${r.critique.files.join(', ')}\ndependsOn: ${r.critique.dependsOn.join(', ')}\n${r.critique.finalSpec.slice(0, 2500)}`).join('\n\n')
const batching = await agent(`${CONTEXT}\n\nGroup these accepted mechanics, plus one extra item "simplicity-guardrails" (applies the auditor's guardrail changes; files: ${[...new Set((audit?.guardrails || []).flatMap(g => g.files))].join(', ') || 'various'}), into implementation batches that run after all planned items land. Items inside one batch are implemented in parallel git worktrees and squash-merged, so they must touch disjoint code regions where possible; respect dependsOn ordering; put simplicity-guardrails in the LAST batch so it can also cover the new mechanics; minimize the number of batches (at most 8 items per batch). Return batches only; do not write files.\n\n${specsText}`, { label: 'batch:ttd', phase: 'Batch', schema: BATCH })

return { accepted: accepted.map(r => ({ id: r.critique.id, title: r.design.title, fit: r.design.fit, verdict: r.critique.verdict, reason: r.critique.reason, spec: r.critique.finalSpec, tests: r.critique.tests, files: r.critique.files, dependsOn: r.critique.dependsOn, impact: r.critique.impact, effort: r.critique.effort })), rejected, audit, batching }

