const SPEC = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    title: { type: 'string' },
    fit: { type: 'string', description: 'why this belongs in this game, how it stays optional and keeps basic play simple' },
    spec: { type: 'string', description: 'complete, precise implementation spec: data model (fields, defaults, validation), simulation rules with numbers, exact functions/files to change, UI (where, copy, states), save compatibility, determinism, interactions with the planned items' },
    tests: { type: 'string', description: 'node tests to add and browser checks to run/extend' },
    files: { type: 'array', items: { type: 'string' } },
    dependsOn: { type: 'array', items: { type: 'string' }, description: 'planned item ids or other ttd ids that must land first' },
    impact: { type: 'integer', minimum: 1, maximum: 5 },
    effort: { type: 'string', enum: ['S', 'M', 'L'] },
  },
  required: ['id', 'title', 'fit', 'spec', 'tests', 'files', 'dependsOn', 'impact', 'effort'],
}
const CRITIQUE = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    verdict: { type: 'string', enum: ['accept', 'accept-revised', 'reject'] },
    reason: { type: 'string' },
    finalSpec: { type: 'string', description: 'for accept/accept-revised: the final, corrected implementation spec (complete, standalone)' },
    tests: { type: 'string' },
    files: { type: 'array', items: { type: 'string' } },
    dependsOn: { type: 'array', items: { type: 'string' } },
    impact: { type: 'integer', minimum: 1, maximum: 5 },
    effort: { type: 'string', enum: ['S', 'M', 'L'] },
  },
  required: ['id', 'verdict', 'reason', 'finalSpec', 'tests', 'files', 'dependsOn', 'impact', 'effort'],
}
const AUDIT = {
  type: 'object',
  properties: {
    summary: { type: 'string' },
    guardrails: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          target: { type: 'string', description: 'planned item id, landed commit/feature, or "general"' },
          problem: { type: 'string', description: 'how it forces the player or complicates the basic loop, with evidence' },
          change: { type: 'string', description: 'the concrete change to make (copy, default, placement, rule), precise enough to implement' },
          files: { type: 'array', items: { type: 'string' } },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
        },
        required: ['target', 'problem', 'change', 'files', 'severity'],
      },
    },
  },
  required: ['summary', 'guardrails'],
}

phase('Design')
const auditP = agent(`${CONTEXT}\n\nYOU ARE THE SIMPLICITY AND FREEDOM AUDITOR. Review (a) what already landed on branch transport-playability (git -C ${REPO} diff 7be60d3..HEAD -- fun/transport, and the live game served at http://127.0.0.1:8841/fun/transport/ — you may drive it with a Playwright script: Playwright at /Users/vojta/Dev/evangelist-exchange/node_modules/playwright/index.mjs, chromium channel 'chrome', run node with dangerouslyDisableSandbox: true; the game opens at a start menu, use fun/transport/tests/browser-start.mjs createWorldFromMenu) and (b) every remaining planned item spec in ${SP}/specs/ (the ids listed above). Find anything that forces the player (deadlines that hurt, penalties for inaction, mandatory chores, nags, blocking modals, goals presented as obligations, growth gates that make the old simple loop stop working) or that makes the basic loop harder to understand (more steps, more on-screen chrome by default, jargon). Also check the first 5 minutes of a new game stay simple. Return concrete guardrail changes (copy, defaults, placement, rules) precise enough to implement; prefer small changes that keep each feature's value. Scratch: ${SP}/ttd/audit/.`, { label: 'audit:simplicity', phase: 'Design', schema: AUDIT })

const results = await pipeline(
  MECHANICS,
  m => agent(`${CONTEXT}\n\nYOU DESIGN ONE MECHANIC: ${m.id}.\n${m.brief}\n\nRead the relevant code (model.js, settlements.js, industry-simulation.js, economy-pricing.js, data.js, gameplay-insights.js, app.js panels, save codecs/validateGame) and the relevant planned-item specs before designing. Where numbers matter, run node sims (import from ${REPO}/fun/transport/model.js etc.) to calibrate. Produce a spec an engineer can implement without guessing. Keep scope tight: the smallest version that delivers the Transport Tycoon feel while staying optional and simple.`, { label: `design:${m.id}`, phase: 'Design', schema: SPEC }),
  (d, m) => d && agent(`${CONTEXT}\n\nYou are a skeptical lead game designer and engineer reviewing a proposed mechanic for this game. Check: (1) the user's principles — is it optional, safe to ignore, free of penalties for inaction, and does it keep the basic loop and default screen simple? does it fit the calm, elegant design and two-stop route model? (2) is it correct against the actual code (open the functions it names), save-compatible, deterministic, performance-safe on 2048² maps with 10k vehicles; (3) does it duplicate or conflict with planned items (read their specs in ${SP}/specs/) or other proposed mechanics (ttd-achievements, ttd-transit-payment, ttd-full-load, ttd-company-rating, ttd-vehicle-models, ttd-headlines, ttd-industry-dynamics, ttd-town-authority, ttd-mail); (4) are the numbers sane (re-run a quick sim if balance is claimed). Verdict accept, accept-revised (write the corrected complete spec), or reject (say why). Keep what gives the TTD feel or the long-term challenge; cut what does not pay for itself or adds pressure.\n\nPROPOSED SPEC:\n${JSON.stringify(d, null, 1)}`, { label: `critique:${m.id}`, phase: 'Critique', schema: CRITIQUE }).then(c => ({ design: d, critique: c })),
)
const audit = await auditP

const accepted = results.filter(r => r && r.critique && r.critique.verdict !== 'reject')
const rejected = results.filter(r => r && r.critique && r.critique.verdict === 'reject').map(r => ({ id: r.design.id, reason: r.critique.reason }))
log(`${accepted.length} mechanics accepted, ${rejected.length} rejected; ${audit?.guardrails?.length || 0} simplicity guardrails`)

phase('Batch')
const BATCH = {
  type: 'object',
  properties: {
    batches: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, itemIds: { type: 'array', items: { type: 'string' } } }, required: ['name', 'itemIds'] } },
    notes: { type: 'string' },
  },
  required: ['batches', 'notes'],
}
const specsText = accepted.map(r => `### ${r.critique.id} (${r.design.title})\nfiles: ${r.critique.files.join(', ')}\ndependsOn: ${r.critique.dependsOn.join(', ')}\n${r.critique.finalSpec.slice(0, 2500)}`).join('\n\n')
const batching = await agent(`${CONTEXT}\n\nGroup these accepted mechanics, plus one extra item "simplicity-guardrails" (applies the auditor's guardrail changes; files: ${[...new Set((audit?.guardrails || []).flatMap(g => g.files))].join(', ') || 'various'}), into implementation batches that run after all planned items land. Items inside one batch are implemented in parallel git worktrees and squash-merged, so they must touch disjoint code regions where possible; respect dependsOn ordering; put simplicity-guardrails in the LAST batch so it can also cover the new mechanics; minimize the number of batches (at most 8 items per batch). Return batches only; do not write files.\n\n${specsText}`, { label: 'batch:ttd', phase: 'Batch', schema: BATCH })

return { accepted: accepted.map(r => ({ id: r.critique.id, title: r.design.title, fit: r.design.fit, verdict: r.critique.verdict, reason: r.critique.reason, spec: r.critique.finalSpec, tests: r.critique.tests, files: r.critique.files, dependsOn: r.critique.dependsOn, impact: r.critique.impact, effort: r.critique.effort })), rejected, audit, batching }

